-- Dati extra BGG (non mostrati in UI) per la collezione ufficiale. Rigenerare con tools/build-meta.py
on conflict (game_id) do update set bgg_id=excluded.bgg_id,weight=excluded.weight,best_players=excluded.best_players,rec_players=excluded.rec_players,min_age=excluded.min_age,lang_dep=excluded.lang_dep,bgg_rank=excluded.bgg_rank,bgg_avg=excluded.bgg_avg,mechanics=excluded.mechanics,categories=excluded.categories,subdomains=excluded.subdomains,interaction=excluded.interaction,luck=excluded.luck,status='ok',fetched_at=now(),attempts=0,last_error=null;
